"""Static Bible hub, local verse index and complete selected chapter readers."""
import html
import json
import re
from bible_support import load_bible, reference_label, reference_url, chapter_url, selected_chapters
from biblical_content import ARTICLES

H=html.escape

def passage_panel(article):
    refs=article.get('passages',[])
    if not refs:return ''
    excerpt = ''
    if article.get('inline_scripture'):
        book, chapter, first, last = refs[0]
        last = min(last, first + 7)
        bible = load_bible()
        lines = ''.join('<p><sup>' + str(verse) + '</sup> ' + H(bible['verses'][(book, chapter, verse)]['text']) + '</p>' for verse in range(first, last + 1))
        excerpt = '<div class="inline-scripture"><h3>' + H(reference_label((book, chapter, first, last))) + '</h3><blockquote class="scripture-excerpt" cite="' + reference_url((book, chapter, first, last)) + '">' + lines + '</blockquote><p class="muted">World English Bible British Edition. <a href="' + reference_url((book, chapter, first, last)) + '">Continue in the complete local chapter</a>.</p></div>'
    note=article.get('passage_note','The biblical text is the primary reference for the accounts discussed here. Read the complete chapters before comparing the guide\'s interpretation.')
    return '<section id="biblical-passages" class="biblical-passages"><span class="eyebrow">BIBLICAL PRIMARY SOURCES</span><h2>Read the Scripture.</h2><p>'+H(note)+'</p>'+excerpt+'<ul>'+''.join(f'<li><a href="{reference_url(p)}">{H(reference_label(p))} <span aria-hidden="true">&#8594;</span></a></li>' for p in refs)+'</ul><p><a href="/bible/">Explore Assyria in the Bible</a> &middot; <a href="/bible/passages/">Search the verse index</a></p></section>'


def make_pages(write,shell,heading,card,all_articles):
    b=load_bible();m=b['manifest'];selected=selected_chapters(all_articles)
    groups=list(dict.fromkeys(a['bible_group'] for a in ARTICLES))
    chips=''.join(f'<button class="chip {"active" if i==0 else ""}" data-bible-group="{H(group)}" aria-pressed="{"true" if i==0 else "false"}">{H("All guides" if group=="all" else group)}</button>' for i,group in enumerate(['all']+groups))
    guides=''.join(f'<div data-bible-guide="{H(a["bible_group"])}">{card(a)}</div>' for a in ARTICLES)
    verse=H(b['verses'][('ISA',19,25)]['text'])
    extra='<link rel="stylesheet" href="/bible.css"><script defer src="/bible.js"></script>'
    main=f'''<main id="main" class="wrap section bible-page">{heading('SCRIPTURE & ASSYRIAN HISTORY','Assyria in the Bible.','Begin with Scripture. Follow Assyria through the biblical accounts of origins, kings, exile, prophecy, repentance and hope, with the primary passages always close at hand.')}
<div class="bible-principle"><span class="eyebrow">OUR STARTING POINT</span><p>The Bible is the primary source for the events and peoples it records in this collection. Each guide identifies its passages first. Translation choices, literary setting and historical interpretation are explained openly, and additional evidence is cited separately.</p><a class="text-link" href="/articles/bible-reading-guide/">Read our approach &#8594;</a></div>
<div class="bible-feature"><div><span class="eyebrow">A VISION OF BLESSING / ISAIAH 19:23-25</span><h2>Assyria, the work<br>of God's hands.</h2><blockquote>{verse}</blockquote><a href="/bible/read/isa/19/#v-25">Read Isaiah 19 in context &#8594;</a></div><div class="bible-feature-links"><a href="/bible/passages/"><span>THE VERSE INDEX</span>Find a passage.<small>Search {len(b['matches'])} named-reference entries across {len({v['book'] for v in b['matches']})} books.</small>&#8594;</a><a href="/articles/bible-hezekiah-deliverance/"><span>THE PARALLEL ACCOUNTS</span>Jerusalem's deliverance.<small>Read Kings, Isaiah and Chronicles together.</small>&#8594;</a><a href="/articles/bible-jonah/"><span>NINEVEH & COMPASSION</span>The city that repented.<small>Follow Jonah into the New Testament references.</small>&#8594;</a></div></div>
<div class="bible-stats"><span><strong>{len(ARTICLES)}</strong> sourced reading guides</span><span><strong>{len(b['matches'])}</strong> verse index entries</span><span><strong>{len(selected)}</strong> complete chapter readers</span><span><strong>{len(m['books'])}</strong> source books preserved</span></div>
<div class="section-top"><div><span class="eyebrow">FOLLOW THE SCRIPTURAL ACCOUNT</span><h2>Many passages. A connected story.</h2></div></div><div class="filter-chips" role="group" aria-label="Filter Bible guides">{chips}</div><p id="bible-guide-count" class="muted" role="status">{len(ARTICLES)} guides</p><div class="bible-guide-grid">{guides}</div>
<section class="bible-preservation"><div><span class="eyebrow">THE TEXT STAYS HERE</span><h2>Read it. Reference it. Keep it.</h2><p>The source is the public-domain World English Bible British Edition with Deuterocanon (WEBBE). All {m['verses']:,} verse lines in the publisher's text edition are retained in this repository, split by book without changing their bytes. The local reader reproduces the passage wording, including original punctuation.</p><p>Its extended collection includes books with differing canonical status. Old Testament, New Testament and additional books are labelled separately. The choice of this English edition makes the references accessible; it does not prescribe a canon to every Assyrian church or replace its liturgical Bible tradition.</p><p>The source format already omitted translator footnotes, paragraph divisions and introductions. Refer to the publisher's other formats when those are needed. <a href="/articles/bible-reading-guide/">Read the coverage and interpretation notes.</a></p></div><div><h3>Preserved source &amp; methodology</h3><a href="/archive/bible/manifest.json" download>Download the source manifest</a><a href="/archive/bible/concordance.json" download>Download the named-reference index</a><a href="/archive/bible/README.md" download>Read preservation and search methods</a><a href="/archive/bible/source-notice.htm">Read the publisher's public-domain notice</a><a href="https://ebible.org/bible/details.php?id=eng-webbe" target="_blank" rel="noopener">Visit the original Bible edition</a><p>Individual complete source books can be downloaded from each local chapter reader. Bible wording and editorial commentary are presented separately.</p></div></section>
</main>'''
    write('/bible/index.html',shell('Assyria in the Bible','Biblical primary sources about Assyria, with local Scripture readers, verse references and guides to kings, Nineveh, exile, prophecy and hope.','/bible/',main,'bible',extra))
    book_codes={v['book'] for v in b['matches']}
    books=''.join(f'<option value="{book["code"]}">{H(book["name"])}</option>' for book in m['books'] if book['code'] in book_codes)
    terms=''.join(f'<option value="{H(term)}">{H(term)}</option>' for term in __import__('bible_support').ALIASES)
    entries=[]
    for v in b['matches']:
        ref=(v['book'],v['chapter'],v['verse'],v['verse'])
        search=' '.join([reference_label(ref),v['book']+f' {v["chapter"]}:{v["verse"]}',v['text'],*v['terms']]).lower()
        search = re.sub('[\u2010-\u2015\u2212]', '-', search)
        entries.append(f'<article class="bible-entry" data-bible-entry data-book="{v["book"]}" data-chapter="{v["chapter"]}" data-verse="{v["verse"]}" data-collection="{H(v["collection"])}" data-terms="{H(json.dumps(v["terms"]))}" data-search="{H(search)}"><div><span class="eyebrow">{H(v["collection"])}</span><h2><a href="{reference_url(ref)}">{H(reference_label(ref))}</a></h2><span class="bible-match-terms">{H(" / ".join(v["terms"]))}</span></div><div><blockquote>{H(v["text"])}</blockquote><a class="text-link" href="{reference_url(ref)}">Read the complete chapter &#8594;</a></div></article>')
    main=f'''<main id="main" class="wrap section bible-page">{heading('THE BIBLICAL REFERENCE INDEX','Let the text speak.','Search the retained Bible text for Assyria, Nineveh, named rulers and related people and places. Each result links to a complete locally hosted chapter.')}<nav class="bible-breadcrumb"><a href="/bible/">Assyria in the Bible</a> / Verse index</nav><div class="bible-index-note"><p><strong>What this index includes</strong> {len(b['matches'])} verse entries match the published name and alias rules across the complete retained edition. This is a named-reference index, not a claim to capture every indirect allusion. The reading guides add relevant passages without a matching name.</p><p>Some words have more than one referent: Pul in Isaiah 66:19 is in a list of peoples or places, while Pul in 2 Kings 15:19 is a king. Asshurim in Genesis 25:3 and the uncertain Shalman in Hosea 10:14 also require context. Office titles can occur in other royal settings. Matching a term does not establish an Assyrian identity.</p></div><div class="bible-search-controls"><label>Search reference, words or name<input id="bible-query" type="search" placeholder="Try Isaiah 19, Sennacherib or Nineveh" autocomplete="off"></label><label>Collection<select id="bible-collection"><option value="all">All included books</option><option>Old Testament</option><option>New Testament</option><option>Deuterocanon / additional books</option></select></label><label>Book<select id="bible-book"><option value="all">All books</option>{books}</select></label><label>Name or alias<select id="bible-term"><option value="all">All published terms</option>{terms}</select></label><button class="button outline" id="bible-clear" type="button">Reset filters</button></div><p id="bible-result-count" class="muted" role="status">{len(entries)} verse entries. JavaScript adds filtering and pagination.</p><div id="bible-entries">{''.join(entries)}</div><p id="bible-no-results" class="article-note" hidden>No matching entries. Clear a filter or try a different spelling. Related passages without a named match may be covered in the reading guides.</p><button class="button outline" id="bible-more" type="button" hidden>Show more passages</button><div class="bible-index-note"><p>Translation: World English Bible British Edition with Deuterocanon. Public domain. Each indexed verse is reproduced as retained. Additional books are included for coverage and labelled by collection; their canonical status varies by tradition.</p><a href="/archive/bible/concordance.json" download>Download every index entry and the search rules</a> &middot; <a href="/bible/">Return to the reading guides</a></div></main>'''
    write('/bible/passages/index.html',shell('Biblical verse index','Search locally retained biblical references to Assyria, Nineveh, Assyrian rulers and related names.','/bible/passages/',main,'bible',extra))
    by_book={code:[c for code2,c in selected if code2==code] for code,c in selected}
    for code,chapter in selected:
        book=b['books'][code];verses=b['chapters'][(code,chapter)];title=f'{book["name"]} {chapter}'
        links=''.join(f'<a href="{chapter_url(code,c)}"'+(' aria-current="page"' if c==chapter else '')+f'>{c}</a>' for c in by_book[code])
        verse_html=''.join(f'<p id="v-{v["verse"]}"><a class="bible-verse-number" href="#v-{v["verse"]}" aria-label="Verse {v["verse"]}">{v["verse"]}</a><span>{H(v["text"])}</span></p>' for v in verses)
        guide_links=''.join(f'<li><a href="/articles/{a["slug"]}/">{H(a["title"])}</a></li>' for a in ARTICLES if any(p[0]==code and p[1]==chapter for p in a['passages']))
        main=f'''<main id="main" class="wrap section bible-reader"><nav class="bible-breadcrumb"><a href="/bible/">Assyria in the Bible</a> / <a href="/bible/passages/">Verse index</a> / {H(title)}</nav><div class="page-heading"><span class="eyebrow">{H(book['collection'])} / WEBBE</span><h1>{H(title)}</h1><p>The complete chapter from the locally retained World English Bible British Edition with Deuterocanon. Biblical text follows; reading notes are separate below.</p></div><div class="bible-reader-layout"><aside><span class="eyebrow">CHAPTERS IN THIS READING COLLECTION</span><nav aria-label="Available chapters of {H(book['name'])}" class="bible-chapter-list">{links}</nav><label class="bible-verse-jump">Go to verse<select id="bible-verse-jump">{''.join(f'<option value="v-{v["verse"]}">{v["verse"]}</option>' for v in verses)}</select></label><a class="text-link" href="/archive/bible/{book['path']}" download>Download complete {H(book['name'])} source &#8595;</a></aside><div><blockquote class="bible-chapter-text" cite="https://ebible.org/eng-webbe/">{verse_html}</blockquote><div class="bible-reader-notes"><span class="eyebrow">TEXT &amp; READING CONTEXT</span><p>This is Scripture from the publisher's verse-per-line edition. Paragraph breaks are shown per verse. The source format does not contain translator notes. Punctuation and wording are retained; the verse number links are added for reference.</p><p>{'This book belongs to the source edition\'s extended collection. Its canonical status varies among Christian traditions.' if book['collection']=='Deuterocanon / additional books' else 'This chapter is included because it contains an indexed name or a passage selected by a reading guide.'}</p>{'<h2>Related reading guides</h2><ul>'+guide_links+'</ul>' if guide_links else ''}<p><a href="/archive/bible/source-notice.htm">Publisher notice</a> &middot; <a href="/archive/bible/manifest.json">Source and hashes</a> &middot; <a href="/bible/passages/">Search biblical references</a></p></div></div></div></main>'''
        write(chapter_url(code,chapter)+'index.html',shell(title+' | Scripture reader','Read '+title+' in the locally retained public-domain Bible, with verse references and related Assyrian history guides.',chapter_url(code,chapter),main,'bible',extra))
    payload=dict(edition=m['edition'],method='Case-insensitive whole-name matching of the published regular expressions against the complete retained edition. One entry per verse even when multiple terms match. No stemming, substring matching of assurance, or inference of ethnicity. Guide-selected context passages are additional to this index.',aliases=__import__('bible_support').ALIASES,source_manifest='/archive/bible/manifest.json',entries=b['matches'])
    write('/archive/bible/concordance.json',json.dumps(payload,indent=2,ensure_ascii=False)+'\n')
    return ['/bible/','/bible/passages/']+[chapter_url(code,c) for code,c in selected]
